<script setup lang="ts">
const {ensure,auth}=usePrivatePage(),api=useBookingApi(),toast=useAppToast(),{t}=useSiteLocale()
useSeoMeta({title:'تنظیمات حساب',robots:'noindex,nofollow'})
const loading=ref(true),busy=ref(false),error=ref(''),saved=ref(false),smsEnabled=ref(false)
const password=reactive({current_password:'',password:'',password_confirmation:''})
const verifyForPassword=ref(false)
const hasPassword=computed(()=>auth.client.value?.has_password!==false)
onMounted(async()=>{if(!await ensure()){loading.value=false;return}try{const [response,me]=await Promise.all([api.notificationPreferences(),api.authMe()]);smsEnabled.value=Boolean(response.data?.sms_enabled);auth.client.value=me.data}catch(e){error.value=bookingMessage(e,t)}finally{loading.value=false}})
async function savePreferences(){if(busy.value)return;busy.value=true;error.value='';saved.value=false;try{const result=await api.updateNotificationPreferences({sms_enabled:smsEnabled.value});smsEnabled.value=Boolean(result.data?.sms_enabled);saved.value=true;toast.success('تنظیمات اعلان ذخیره شد.')}catch(e){error.value=bookingMessage(e,t)}finally{busy.value=false}}
async function changePassword(){if(busy.value)return;if(!hasPassword.value&&(password.password.length<12||!/[a-z]/.test(password.password)||!/[A-Z]/.test(password.password)||!/[0-9]/.test(password.password))){error.value='رمز باید دست‌کم ۱۲ نویسه و شامل حروف کوچک، بزرگ و عدد باشد.';return}if(password.password!==password.password_confirmation){error.value='تکرار رمز با رمز جدید یکسان نیست.';return}busy.value=true;error.value='';saved.value=false;try{if(hasPassword.value){await api.changePassword(password);toast.success('رمز عبور با موفقیت تغییر کرد.');auth.clear();await navigateTo('/account/login')}else{await api.setPassword({password:password.password,password_confirmation:password.password_confirmation});auth.client.value=(await api.authMe()).data;saved.value=true;toast.success('رمز عبور شما ثبت شد.');password.password='';password.password_confirmation=''}}catch(e){error.value=otpErrorMessage(e)}finally{busy.value=false}}
</script>
<template><section class="account-subpage account-settings-page"><h1>تنظیمات حساب</h1><p v-if="loading">در حال دریافت تنظیمات…</p><template v-else>
 <div class="account-settings-grid">
 <article class="card settings-card settings-sms"><div class="settings-card-heading"><h2>یادآوری پیامکی</h2></div><p class="settings-description">رضایت دریافت یادآوری نوبت را مدیریت کنید.</p><form class="booking-form" @submit.prevent="savePreferences"><label class="filter-check"><input v-model="smsEnabled" type="checkbox"> دریافت یادآوری نوبت با پیامک</label><button class="btn" :disabled="busy">{{busy?'در حال ذخیره…':'ذخیره'}}</button></form></article>
 <article class="card settings-card settings-password"><div class="settings-card-heading"><h2>{{hasPassword?'تغییر رمز عبور':'تعیین رمز عبور'}}</h2></div><template v-if="!hasPassword"><p class="settings-description">برای تعیین رمز، شماره موبایل تأییدشده حساب را دوباره تأیید کنید.</p><button v-if="!verifyForPassword" class="btn" type="button" @click="verifyForPassword=true">تأیید شماره و تعیین رمز</button><template v-else><OtpLoginFlow step-up-only redirect-to="/account/settings" @password-setup-finished="verifyForPassword=false"/><button v-if="verifyForPassword" class="otp-resend" type="button" @click="verifyForPassword=false">بازگشت</button></template></template><form v-else class="booking-form settings-password-form" @submit.prevent="changePassword"><label>رمز فعلی<input v-model="password.current_password" type="password" autocomplete="current-password" required></label><label>رمز جدید<input v-model="password.password" type="password" minlength="12" autocomplete="new-password" required></label><label>تکرار رمز جدید<input v-model="password.password_confirmation" type="password" minlength="12" autocomplete="new-password" required></label><button class="btn" :disabled="busy">{{busy?'در حال ذخیره…':'تغییر رمز'}}</button></form></article></div>
 <div class="settings-notices"><ApiNotice v-if="error">{{error}}</ApiNotice><ApiNotice v-if="saved">تنظیمات ذخیره شد.</ApiNotice></div>
 </template></section></template>
